**The function, verbatim:**

```ts
export const ACTION_TOOL_PREFIX = 'action_';
export const ACTION_TOOL_OBJECT_SEPARATOR = '__';
export const AI_TOOL_NAME_MAX_LENGTH = 64;
const SHORTENED_HASH_LENGTH = 8;

/** FNV-1a, 32-bit, as 8 lowercase hex characters. Pure and runtime-agnostic. */
function fnv1a32Hex(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(SHORTENED_HASH_LENGTH, '0');
}

export function actionToolName(
  action: { name: string; objectName?: string },
  prefix: string = ACTION_TOOL_PREFIX,
): string {
  if (!action.objectName) return `${prefix}${action.name}`;
  const qualified = `${action.objectName}${ACTION_TOOL_OBJECT_SEPARATOR}${action.name}`;
  const full = `${prefix}${qualified}`;
  if (full.length <= AI_TOOL_NAME_MAX_LENGTH) return full;
  const headLength = Math.max(0, AI_TOOL_NAME_MAX_LENGTH - prefix.length - 1 - SHORTENED_HASH_LENGTH);
  const hash = fnv1a32Hex(`${action.objectName}:${action.name}`);
  return `${prefix}${qualified.slice(0, headLength)}_${hash}`;
}
```

**The four open questions, as the code answers them:**
- Characters outside `[a-z0-9_]`: not mapped. Inputs are taken as already snake_case (object and action names are); nothing is replaced.
- Lower-casing: none.
- Hash input encoding: UTF-16 code units (`charCodeAt`), not UTF-8 bytes. Identical for ASCII names.
- Hex: lowercase, zero-padded to 8 (`padStart(8, '0')`). Head length = 64 − len(prefix) − 1 − 8 = 48 for `action_`.

